import { Badge } from "@/components/ui/badge";
import { DndContext, DragOverlay, KeyboardSensor, MouseSensor, TouchSensor, closestCorners, useDraggable, useDroppable, useSensor, useSensors, type DragEndEvent, type DragStartEvent } from "@dnd-kit/core";
import { CSS } from "@dnd-kit/utilities";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { projectProgress, projectTasksForProgress, projectTasksForView } from "@/lib/projectProgress";
import { buildProjectTimelineItems, projectsWithoutTimelineDate } from "@/lib/projectTimeline";
import { taskStatusTransitionInput, type KanbanTaskStatus } from "@/lib/projectTaskTransition";
import { buildProjectWorkspaceOverview, projectFocusQueue, type ProjectFocusFilter, type ProjectFocusOrder } from "@/lib/projectWorkspace";
import { trpc } from "@/lib/trpc";
import { Archive, ArchiveRestore, ArrowDownUp, CalendarDays, CheckCircle2, ChevronRight, CircleDot, Columns3, Filter, FolderKanban, GripVertical, Link2, List, ListChecks, Pencil, Plus, Target, Trash2 } from "lucide-react";
import { FormEvent, useMemo, useState } from "react";
import { toast } from "sonner";

const projectStatusLabel: Record<string, string> = { active: "Activo", planned: "Planeado", paused: "En pausa", closed: "Cerrado", archived: "Archivado" };
const taskStatusLabel: Record<string, string> = { pending: "Pendiente", in_progress: "En curso", waiting: "Esperando", completed: "Completada", cancelled: "Cancelada" };
const milestoneStatusLabel: Record<string, string> = { planned: "Planeado", in_progress: "En curso", completed: "Completado", archived: "Archivado" };
const priorityLabel: Record<string, string> = { critical: "Crítica", high: "Alta", medium: "Media", low: "Baja" };
const toDate = (value: Date | string | null | undefined) => value ? new Date(value).toISOString().slice(0, 10) : "";
const formatDate = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleDateString("es-MX", { day: "numeric", month: "short", year: "numeric" }) : "Sin fecha";

export default function Projects() {
  const { data, isLoading } = trpc.finance.workspace.get.useQuery();
  const utils = trpc.useUtils();
  const [view, setView] = useState<"list" | "kanban" | "calendar">("list");
  const [showArchived, setShowArchived] = useState(false);
  const [projectEditing, setProjectEditing] = useState<any | null>(null);
  const [projectOpen, setProjectOpen] = useState(false);
  const [milestoneEditing, setMilestoneEditing] = useState<any | null>(null);
  const [milestoneProjectId, setMilestoneProjectId] = useState<number | null>(null);
  const [taskEditing, setTaskEditing] = useState<any | null>(null);
  const [taskProjectId, setTaskProjectId] = useState<number | null>(null);
  const [planDraft, setPlanDraft] = useState(false);
  const [focusFilter, setFocusFilter] = useState<ProjectFocusFilter>("all");
  const [focusOrder, setFocusOrder] = useState<ProjectFocusOrder>("urgency");
  const [draggedTask, setDraggedTask] = useState<any | null>(null);
  const [dropStatus, setDropStatus] = useState<string | null>(null);
  const [pendingTaskMove, setPendingTaskMove] = useState<{ task: any; status: KanbanTaskStatus } | null>(null);
  const refresh = async () => { await utils.finance.workspace.get.invalidate(); await utils.finance.dashboard.invalidate(); };
  const projectSave = trpc.finance.workspace.projectSave.useMutation({ onSuccess: async () => { await refresh(); setProjectOpen(false); setProjectEditing(null); setPlanDraft(false); toast.success("Proyecto guardado."); }, onError: error => toast.error(error.message) });
  const projectRemove = trpc.finance.workspace.projectRemove.useMutation({ onSuccess: async () => { await refresh(); toast.success("Proyecto eliminado."); }, onError: error => toast.error(error.message) });
  const milestoneSave = trpc.finance.projectMilestones.save.useMutation({ onSuccess: async () => { await refresh(); setMilestoneEditing(null); setMilestoneProjectId(null); toast.success("Parte del proyecto guardada."); }, onError: error => toast.error(error.message) });
  const milestoneRemove = trpc.finance.projectMilestones.remove.useMutation({ onSuccess: async () => { await refresh(); toast.success("Parte del proyecto eliminada."); }, onError: error => toast.error(error.message) });
  const taskSave = trpc.finance.tasks.save.useMutation({ onSuccess: async () => { await refresh(); setTaskEditing(null); setTaskProjectId(null); toast.success("Tarea guardada."); }, onError: error => toast.error(error.message) });
  const taskStatusSave = trpc.finance.tasks.save.useMutation({ onSuccess: async () => { await refresh(); setPendingTaskMove(null); toast.success("Estado de tarea actualizado."); }, onError: error => toast.error(error.message) });
  const taskArchive = trpc.finance.tasks.archive.useMutation({ onSuccess: async () => { await refresh(); toast.success("Estado de archivo actualizado."); }, onError: error => toast.error(error.message) });
  const taskRemove = trpc.finance.tasks.remove.useMutation({ onSuccess: async () => { await refresh(); toast.success("Tarea eliminada y eventos manuales desvinculados."); }, onError: error => toast.error(error.message) });

  const isOwner = data?.workspaceAccess.role === "owner";
  const allProjects = data?.projects ?? [];
  const allMilestones = data?.projectMilestones ?? [];
  const allTasks = data?.tasks ?? [];
  const projects = useMemo(() => allProjects.filter((project: any) => showArchived || project.status !== "archived"), [allProjects, showArchived]);
  const milestones = allMilestones.filter((milestone: any) => showArchived || milestone.status !== "archived");
  const tasks = projectTasksForView(allTasks, showArchived);
  const progressTasks = projectTasksForProgress(allTasks);
  const overview = useMemo(() => buildProjectWorkspaceOverview(projects, progressTasks), [projects, progressTasks]);
  const focusTasks = useMemo(() => projectFocusQueue(allTasks, 6, focusFilter, focusOrder), [allTasks, focusFilter, focusOrder]);
  const openNewProject = (draft = false) => { setProjectEditing(null); setPlanDraft(draft); setProjectOpen(true); };
  const openTask = (projectId: number, task: any | null = null) => { setTaskEditing(task); setTaskProjectId(projectId); };
  const requestTaskMove = (task: any, status: KanbanTaskStatus) => { if (task.status !== status) setPendingTaskMove({ task, status }); };
  const confirmTaskMove = () => { if (pendingTaskMove) taskStatusSave.mutate(taskStatusTransitionInput(pendingTaskMove.task, pendingTaskMove.status)); };

  if (isLoading || !data) return <section className="page-loading"><p>Organizando proyectos privados…</p></section>;

  const projectActions = { onEditProject: (project: any) => { setProjectEditing(project); setPlanDraft(false); setProjectOpen(true); }, onNewMilestone: (id: number) => { setMilestoneEditing(null); setMilestoneProjectId(id); }, onEditMilestone: (milestone: any) => { setMilestoneEditing(milestone); setMilestoneProjectId(milestone.projectId); }, onNewTask: (id: number) => openTask(id), onEditTask: (task: any) => openTask(task.projectId, task), onArchiveProject: (project: any) => projectSave.mutate({ ...serializeProject(project), status: "archived" }), onRemoveProject: (project: any) => { if (window.confirm("¿Eliminar este proyecto vacío? Los proyectos con tareas deben archivarse o vaciarse primero.")) projectRemove.mutate({ id: project.id }); }, onArchiveTask: (task: any) => taskArchive.mutate({ id: task.id, archived: !task.archivedAt }), onRemoveTask: (task: any) => { if (window.confirm("¿Eliminar esta tarea? Los eventos manuales vinculados se conservarán, pero quedarán desvinculados.")) taskRemove.mutate({ id: task.id }); }, onRemoveMilestone: (milestone: any) => { if (window.confirm("¿Eliminar esta parte vacía del proyecto?")) milestoneRemove.mutate({ id: milestone.id }); } };

  return <section className="space-y-5 pb-6">
    <ProjectWorkspaceHeader overview={overview} isOwner={isOwner} onNewProject={() => openNewProject()} onOpenDraft={() => openNewProject(true)} />
    <div className="grid items-start gap-5 xl:grid-cols-[16rem_minmax(0,1fr)]">
      <ProjectSidebar active={view} showArchived={showArchived} overview={overview} focusTasks={focusTasks} projects={projects} focusFilter={focusFilter} focusOrder={focusOrder} onFocusFilterChange={setFocusFilter} onFocusOrderChange={setFocusOrder} onViewChange={setView} onToggleArchived={() => setShowArchived(value => !value)} onEditTask={(task: any) => openTask(task.projectId, task)} />
      <main className="min-w-0">
        {view === "list" ? <ProjectPortfolio projects={projects} milestones={milestones} tasks={tasks} progressTasks={progressTasks} isOwner={isOwner} {...projectActions} /> : null}
        {view === "kanban" ? <ProjectFlowBoard projects={projects} tasks={tasks} isOwner={isOwner} draggedTask={draggedTask} dropStatus={dropStatus} onDragStart={setDraggedTask} onDragOver={setDropStatus} onDragEnd={() => { setDraggedTask(null); setDropStatus(null); }} onDrop={(status: "pending" | "in_progress" | "waiting" | "completed") => { if (draggedTask) requestTaskMove(draggedTask, status); setDraggedTask(null); setDropStatus(null); }} onRequestMove={requestTaskMove} onEditTask={(task: any) => openTask(task.projectId, task)} onNewTask={(id: number) => openTask(id)} /> : null}
        {view === "calendar" ? <ProjectSchedule projects={projects} milestones={milestones} tasks={tasks} isOwner={isOwner} onEditTask={(task: any) => openTask(task.projectId, task)} onEditProject={projectActions.onEditProject} /> : null}
      </main>
    </div>
    <Dialog open={projectOpen} onOpenChange={value => { setProjectOpen(value); if (!value) { setProjectEditing(null); setPlanDraft(false); } }}><ProjectForm project={projectEditing} entities={data.entities} saving={projectSave.isPending} planDraft={planDraft} onSubmit={(input: any) => projectSave.mutate(input)} /></Dialog>
    <Dialog open={milestoneProjectId !== null} onOpenChange={value => { if (!value) { setMilestoneEditing(null); setMilestoneProjectId(null); } }}>{milestoneProjectId !== null ? <MilestoneForm milestone={milestoneEditing} projectId={milestoneProjectId} saving={milestoneSave.isPending} onSubmit={(input: any) => milestoneSave.mutate(input)} /> : null}</Dialog>
    <Dialog open={taskProjectId !== null} onOpenChange={value => { if (!value) { setTaskEditing(null); setTaskProjectId(null); } }}>{taskProjectId !== null ? <TaskForm task={taskEditing} projectId={taskProjectId} milestones={milestones.filter((milestone: any) => milestone.projectId === taskProjectId && milestone.status !== "archived")} transactions={data.transactions} saving={taskSave.isPending} onSubmit={(input: any) => taskSave.mutate(input)} /> : null}</Dialog>
    <Dialog open={Boolean(pendingTaskMove)} onOpenChange={value => { if (!value && !taskStatusSave.isPending) setPendingTaskMove(null); }}><DialogContent className="sm:max-w-md"><DialogHeader><p className="eyebrow">Cambio de estado</p><DialogTitle>¿Mover esta tarea?</DialogTitle><DialogDescription>{pendingTaskMove ? <>«{pendingTaskMove.task.title}» pasará de <strong>{taskStatusLabel[pendingTaskMove.task.status]}</strong> a <strong>{taskStatusLabel[pendingTaskMove.status]}</strong>. El cambio se guarda sólo si lo confirmas.</> : null}</DialogDescription></DialogHeader><div className="flex flex-col-reverse gap-2 pt-2 sm:flex-row sm:justify-end"><Button variant="outline" disabled={taskStatusSave.isPending} onClick={() => setPendingTaskMove(null)}>Cancelar</Button><Button className="btn-primary" disabled={taskStatusSave.isPending} onClick={confirmTaskMove}>{taskStatusSave.isPending ? "Actualizando…" : "Confirmar cambio"}</Button></div></DialogContent></Dialog>
  </section>;
}

function ProjectWorkspaceHeader({ overview, isOwner, onNewProject, onOpenDraft }: any) {
  return <header className="border-b border-border/80 pb-5"><div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><p className="eyebrow">Planificación personal</p><h1 className="mt-1 text-3xl font-semibold tracking-[-0.05em]">Proyectos</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">Un lugar para decidir qué sigue, organizar entregables y revisar el avance de tus iniciativas personales y empresariales.</p></div>{isOwner ? <div className="flex flex-wrap gap-2"><Button variant="outline" onClick={onOpenDraft}>Abrir borrador</Button><Button className="btn-primary" onClick={onNewProject}><Plus className="mr-1.5 size-4"/>Nuevo proyecto</Button></div> : null}</div><div className="mt-5 grid grid-cols-2 gap-2 sm:flex sm:flex-wrap">{[{ label: "Activos", value: overview.activeProjects, tone: "text-primary" }, { label: "Pendientes", value: overview.openTasks, tone: "text-amber-700" }, { label: "Cerradas", value: overview.closedTasks, tone: "text-emerald-700" }, { label: "Avance", value: `${overview.percent}%`, tone: "text-primary" }].map(metric => <div className="rounded-xl border bg-card px-3 py-2.5 shadow-sm sm:min-w-28" key={metric.label}><span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground">{metric.label}</span><strong className={`mt-1 block text-lg font-semibold tracking-[-0.03em] ${metric.tone}`}>{metric.value}</strong></div>)}</div></header>;
}

function ProjectSidebar({ active, showArchived, overview, focusTasks, projects, focusFilter, focusOrder, onFocusFilterChange, onFocusOrderChange, onViewChange, onToggleArchived, onEditTask }: any) {
  const options = [{ value: "list", label: "Proyectos", icon: List, count: overview.totalProjects }, { value: "kanban", label: "Flujo", icon: Columns3, count: overview.openTasks }, { value: "calendar", label: "Calendario", icon: CalendarDays, count: null }];
  const projectById = new Map<number, any>(projects.map((project: any) => [project.id, project]));
  return <aside className="space-y-3 xl:sticky xl:top-4"><nav className="rounded-xl border bg-card p-1.5 shadow-sm" aria-label="Navegación de Proyectos"><div className="grid grid-cols-3 gap-1 xl:grid-cols-1">{options.map(option => { const Icon = option.icon; const selected = active === option.value; return <button type="button" key={option.value} className={`flex min-w-0 items-center justify-center gap-2 rounded-lg px-2 py-2.5 text-sm font-semibold transition xl:justify-start xl:px-3 ${selected ? "bg-primary text-primary-foreground shadow-sm" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`} aria-current={selected ? "page" : undefined} onClick={() => onViewChange(option.value)}><Icon className="size-4 shrink-0"/><span className="hidden truncate xl:inline">{option.label}</span><span className="sr-only">{option.label}</span>{option.count !== null ? <span className={`hidden min-w-6 place-items-center rounded-full px-1.5 py-0.5 text-[10px] xl:grid ${selected ? "bg-white/15 text-white" : "bg-muted text-muted-foreground"}`}>{option.count}</span> : null}</button>; })}</div><div className="mx-2 my-1.5 hidden border-t xl:block"/><button type="button" className="hidden w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-xs font-semibold text-muted-foreground transition hover:bg-muted hover:text-foreground xl:flex" onClick={onToggleArchived}><Archive className="size-4"/><span>{showArchived ? "Ocultar archivados" : "Ver archivados"}</span></button></nav><div className="rounded-xl border bg-card shadow-sm xl:hidden"><details className="group"><summary className="flex cursor-pointer list-none items-center justify-between gap-3 px-3.5 py-3"><span className="flex items-center gap-2"><span className="grid size-7 place-items-center rounded-lg bg-primary/10 text-primary"><ListChecks className="size-3.5"/></span><span><strong className="block text-xs font-semibold">En tu radar</strong><small className="block text-[10px] text-muted-foreground">{overview.openTasks} tareas abiertas</small></span></span><ChevronRight className="size-4 text-muted-foreground transition-transform group-open:rotate-90"/></summary><div className="border-t p-3"><ProjectFocusQueue tasks={focusTasks} projectById={projectById} focusFilter={focusFilter} focusOrder={focusOrder} onFocusFilterChange={onFocusFilterChange} onFocusOrderChange={onFocusOrderChange} onEditTask={onEditTask}/><button type="button" className="mt-3 flex w-full items-center justify-center gap-2 rounded-lg bg-muted px-3 py-2 text-xs font-semibold text-muted-foreground" onClick={onToggleArchived}><Archive className="size-3.5"/>{showArchived ? "Ocultar archivados" : "Ver archivados"}</button></div></details></div><section className="hidden rounded-xl border bg-card p-4 shadow-sm xl:block"><div className="flex items-center gap-2"><span className="grid size-7 place-items-center rounded-lg bg-primary/10 text-primary"><ListChecks className="size-3.5"/></span><div><p className="text-xs font-semibold">En tu radar</p><p className="text-[10px] text-muted-foreground">Prioriza tus próximas tareas</p></div></div><ProjectFocusQueue tasks={focusTasks} projectById={projectById} focusFilter={focusFilter} focusOrder={focusOrder} onFocusFilterChange={onFocusFilterChange} onFocusOrderChange={onFocusOrderChange} onEditTask={onEditTask}/></section></aside>;
}

function ProjectFocusQueue({ tasks, projectById, focusFilter, focusOrder, onFocusFilterChange, onFocusOrderChange, onEditTask }: any) { return <><div className="mt-3 grid grid-cols-2 gap-2"><div><Label className="sr-only" htmlFor="focus-filter">Filtrar tareas</Label><Select value={focusFilter} onValueChange={onFocusFilterChange}><SelectTrigger id="focus-filter" className="h-8 text-[11px]"><Filter className="mr-1 size-3"/><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">Todas</SelectItem><SelectItem value="urgent">Urgentes</SelectItem><SelectItem value="week">Esta semana</SelectItem><SelectItem value="priority">Alta prioridad</SelectItem><SelectItem value="unscheduled">Sin fecha</SelectItem></SelectContent></Select></div><div><Label className="sr-only" htmlFor="focus-order">Ordenar tareas</Label><Select value={focusOrder} onValueChange={onFocusOrderChange}><SelectTrigger id="focus-order" className="h-8 text-[11px]"><ArrowDownUp className="mr-1 size-3"/><SelectValue/></SelectTrigger><SelectContent><SelectItem value="urgency">Por urgencia</SelectItem><SelectItem value="date">Por fecha</SelectItem><SelectItem value="priority">Por prioridad</SelectItem></SelectContent></Select></div></div>{tasks.length ? <div className="mt-3 space-y-1">{tasks.map((task: any) => { const project = projectById.get(task.projectId); return <button type="button" key={task.id} onClick={() => onEditTask(task)} className="flex w-full items-center gap-2 rounded-lg px-2 py-2 text-left transition hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"><span className="size-1.5 shrink-0 rounded-full" style={{ backgroundColor: project?.color ?? "var(--primary)" }}/><span className="min-w-0 flex-1"><strong className="block truncate text-xs font-medium">{task.title}</strong><small className="mt-0.5 block truncate text-[10px] text-muted-foreground">{project?.name ?? "Sin proyecto"}{task.dueAt ? ` · ${formatDate(task.dueAt)}` : " · Sin fecha"}</small></span></button>; })}</div> : <p className="mt-3 rounded-lg bg-muted/50 p-3 text-xs leading-5 text-muted-foreground">No hay tareas para este filtro.</p>}</>; }

function ProjectPortfolio({ projects, milestones, tasks, progressTasks, isOwner, onEditProject, onNewMilestone, onEditMilestone, onNewTask, onEditTask, onArchiveProject, onRemoveProject, onArchiveTask, onRemoveTask, onRemoveMilestone }: any) { return <section className="overflow-hidden rounded-2xl border bg-card shadow-sm"><div className="flex flex-col gap-3 border-b bg-muted/20 px-4 py-4 sm:flex-row sm:items-end sm:justify-between sm:px-5"><div><p className="eyebrow">Vista principal</p><h2 className="mt-1 text-xl font-semibold tracking-[-0.04em]">Portafolio de proyectos</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Cada fila concentra el estado, avance y próximas acciones de un proyecto.</p></div><span className="inline-flex w-fit items-center gap-1.5 rounded-full border bg-card px-3 py-1.5 text-xs font-semibold text-muted-foreground"><FolderKanban className="size-3.5"/>{projects.length} proyectos</span></div>{projects.length ? <div className="divide-y">{projects.map((project: any) => <ProjectWorkRow key={project.id} project={project} milestones={milestones.filter((milestone: any) => milestone.projectId === project.id)} tasks={tasks.filter((task: any) => task.projectId === project.id)} progressTasks={progressTasks.filter((task: any) => task.projectId === project.id)} isOwner={isOwner} onEditProject={() => onEditProject(project)} onNewMilestone={() => onNewMilestone(project.id)} onEditMilestone={onEditMilestone} onNewTask={() => onNewTask(project.id)} onEditTask={onEditTask} onArchiveProject={() => onArchiveProject(project)} onRemoveProject={() => onRemoveProject(project)} onArchiveTask={onArchiveTask} onRemoveTask={onRemoveTask} onRemoveMilestone={onRemoveMilestone}/>)}</div> : <div className="p-4"><EmptyProjects isOwner={isOwner} onNewProject={onEditProject}/></div>}</section>; }

function ProjectWorkRow({ project, milestones, tasks, progressTasks, isOwner, onEditProject, onNewMilestone, onEditMilestone, onNewTask, onEditTask, onArchiveProject, onRemoveProject, onArchiveTask, onRemoveTask, onRemoveMilestone }: any) { const progress = projectProgress(progressTasks); return <article className="relative p-4 sm:p-5"><div className="absolute inset-y-0 left-0 w-1" style={{ backgroundColor: project.color }}/><div className="pl-2"><header className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="size-2.5 rounded-full" style={{ backgroundColor: project.color }}/><h3 className="truncate text-base font-semibold tracking-[-0.025em] sm:text-lg">{project.name}</h3><ProjectStatusBadge status={project.status}/></div><p className="mt-1.5 text-xs text-muted-foreground">{project.entityId ? "Asociado a entidad" : "Proyecto personal"} <span className="mx-1 text-border">·</span> Meta: {formatDate(project.targetAt)}</p>{project.notes ? <p className="mt-3 line-clamp-2 max-w-3xl text-sm leading-6 text-muted-foreground">{project.notes}</p> : null}</div><div className="flex flex-wrap items-center gap-1.5">{isOwner ? <><Button size="sm" variant="outline" onClick={onNewTask}><Plus className="mr-1.5 size-3.5"/>Tarea</Button><Button size="icon" variant="ghost" className="size-8" aria-label="Editar proyecto" onClick={onEditProject}><Pencil className="size-4"/></Button>{project.status !== "archived" ? <Button size="icon" variant="ghost" className="size-8" aria-label="Archivar proyecto" onClick={onArchiveProject}><Archive className="size-4"/></Button> : null}<Button size="icon" variant="ghost" className="size-8 text-muted-foreground hover:bg-rose-50 hover:text-rose-700" aria-label="Eliminar proyecto" onClick={onRemoveProject}><Trash2 className="size-4"/></Button></> : null}</div></header><div className="mt-5 grid gap-4 lg:grid-cols-[12rem_minmax(0,1fr)]"><section className="rounded-xl border bg-muted/20 p-3.5"><div className="flex items-baseline justify-between gap-3"><div><p className="text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground">Avance</p><p className="mt-1 text-xs font-medium">{progress.total ? `${progress.completed} de ${progress.total} cerradas` : "Sin tareas"}</p></div><strong className="text-2xl font-semibold tracking-[-0.05em]" style={{ color: project.color }}>{progress.percent}%</strong></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-card" role="progressbar" aria-label={`Avance de ${project.name}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress.percent}><span className="block h-full rounded-full transition-[width] duration-200" style={{ width: `${progress.percent}%`, backgroundColor: project.color }}/></div><div className="mt-3 flex gap-2 text-[10px] text-muted-foreground"><span>{milestones.length} partes</span><span>·</span><span>{tasks.length} visibles</span></div></section><div className="grid gap-3 md:grid-cols-2"><ProjectWorkSection title="Partes" icon={Target} color={project.color} items={milestones} empty="Divide el proyecto si te ayuda a organizar entregables." isOwner={isOwner} onAdd={onNewMilestone} onEdit={onEditMilestone} onRemove={onRemoveMilestone} type="milestone"/><ProjectWorkSection title="Tareas" icon={ListChecks} color={project.color} items={tasks} empty="Crea una tarea para iniciar el seguimiento." isOwner={isOwner} onAdd={onNewTask} onEdit={onEditTask} onArchive={onArchiveTask} onRemove={onRemoveTask} type="task"/></div></div></div></article>; }

function ProjectWorkSection({ title, icon: Icon, color, items, empty, isOwner, onAdd, onEdit, onArchive, onRemove, type }: any) { const isTask = type === "task"; return <section className="min-w-0 rounded-xl border border-border/80 bg-card"><div className="flex items-center justify-between gap-3 border-b px-3 py-2.5"><div className="flex items-center gap-2"><Icon className="size-3.5" style={{ color }}/><p className="text-xs font-semibold">{title}</p><span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">{items.length}</span></div>{isOwner ? <Button size="icon" variant="ghost" className="size-7" aria-label={`Añadir ${title.toLowerCase()}`} onClick={onAdd}><Plus className="size-3.5"/></Button> : null}</div>{items.length ? <div className="max-h-48 divide-y overflow-y-auto">{items.map((item: any) => <div className="group flex items-center gap-2 px-3 py-2.5" key={item.id}><span className="size-1.5 shrink-0 rounded-full" style={{ backgroundColor: color }}/><button type="button" className="min-w-0 flex-1 text-left" disabled={!isOwner} onClick={() => isOwner && onEdit(item)}><strong className={`block truncate text-xs font-medium ${isTask && item.status === "completed" ? "text-muted-foreground line-through" : ""}`}>{item.title}</strong><small className="mt-0.5 flex items-center gap-1 truncate text-[10px] text-muted-foreground">{isTask ? <>{taskStatusLabel[item.status] ?? item.status}{item.dueAt ? ` · ${formatDate(item.dueAt)}` : ""}{item.linkedTransactionId ? <><span>·</span><Link2 className="size-3" aria-label="Movimiento vinculado"/></> : null}</> : `${milestoneStatusLabel[item.status] ?? item.status}${item.targetAt ? ` · ${formatDate(item.targetAt)}` : ""}`}</small></button>{isOwner ? <div className="flex shrink-0 opacity-100 transition-opacity sm:opacity-0 sm:group-hover:opacity-100"><Button size="icon" variant="ghost" className="size-7" aria-label={`Editar ${isTask ? "tarea" : "parte"}`} onClick={() => onEdit(item)}><Pencil className="size-3.5"/></Button>{isTask && onArchive ? <Button size="icon" variant="ghost" className="size-7" aria-label={item.archivedAt ? "Restaurar tarea" : "Archivar tarea"} onClick={() => onArchive(item)}>{item.archivedAt ? <ArchiveRestore className="size-3.5"/> : <Archive className="size-3.5"/>}</Button> : null}<Button size="icon" variant="ghost" className="size-7 text-muted-foreground hover:bg-rose-50 hover:text-rose-700" aria-label={`Eliminar ${isTask ? "tarea" : "parte"}`} onClick={() => onRemove(item)}><Trash2 className="size-3.5"/></Button></div> : null}</div>)}</div> : <p className="px-3 py-5 text-xs leading-5 text-muted-foreground">{empty}</p>}</section>; }

function ProjectFlowBoard({ projects, tasks, isOwner, draggedTask, dropStatus, onDragStart, onDragOver, onDragEnd, onDrop, onRequestMove, onEditTask, onNewTask }: any) {
  const columns = ["pending", "in_progress", "waiting", "completed"] as const;
  const sensors = useSensors(useSensor(MouseSensor, { activationConstraint: { distance: 4 } }), useSensor(TouchSensor, { activationConstraint: { delay: 180, tolerance: 8 } }), useSensor(KeyboardSensor));
  const projectById = new Map<number, any>(projects.map((project: any) => [project.id, project]));
  const handleDragStart = (event: DragStartEvent) => { const task = tasks.find((item: any) => `task-${item.id}` === String(event.active.id)); if (task) onDragStart(task); };
  const handleDragEnd = (event: DragEndEvent) => { const target = String(event.over?.id ?? ""); const status = target.replace("kanban-", ""); if (columns.includes(status as typeof columns[number])) onDrop(status as typeof columns[number]); else onDragEnd(); };
  return <DndContext sensors={sensors} collisionDetection={closestCorners} onDragStart={handleDragStart} onDragOver={event => { const status = String(event.over?.id ?? "").replace("kanban-", ""); onDragOver(columns.includes(status as typeof columns[number]) ? status : null); }} onDragCancel={onDragEnd} onDragEnd={handleDragEnd}><section className="rounded-2xl border bg-card shadow-sm"><header className="flex flex-col gap-3 border-b px-4 py-4 sm:flex-row sm:items-end sm:justify-between sm:px-5"><div><p className="eyebrow">Flujo de trabajo</p><h2 className="mt-1 text-xl font-semibold tracking-[-0.04em]">Tablero</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Arrastra una tarjeta con el control lateral o usa su selector de estado. Todo cambio se confirma antes de guardarse.</p></div>{isOwner && projects.length ? <div className="flex max-w-full gap-1 overflow-x-auto pb-1">{projects.map((project: any) => <Button type="button" size="sm" variant="outline" className="shrink-0" key={project.id} onClick={() => onNewTask(project.id)}><Plus className="mr-1.5 size-3.5"/><span className="max-w-28 truncate">{project.name}</span></Button>)}</div> : null}</header>{projects.length ? <div className="overflow-x-auto p-4 sm:p-5"><div className="grid min-w-[880px] grid-cols-4 gap-3">{columns.map(status => <ProjectFlowColumn key={status} status={status} projects={projects} tasks={tasks} isOwner={isOwner} isDropTarget={dropStatus === status} onEditTask={onEditTask} onRequestMove={onRequestMove}/>)}</div></div> : <div className="p-4"><EmptyProjects isOwner={false}/></div>}</section><DragOverlay dropAnimation={{ duration: 180, easing: "cubic-bezier(0.23, 1, 0.32, 1)" }}>{draggedTask ? <TaskDragPreview task={draggedTask} project={projectById.get(draggedTask.projectId)}/> : null}</DragOverlay></DndContext>;
}
function ProjectFlowColumn({ status, projects, tasks, isOwner, isDropTarget, onEditTask, onRequestMove }: any) { const { setNodeRef, isOver } = useDroppable({ id: `kanban-${status}`, disabled: !isOwner }); const items = tasks.filter((task: any) => task.status === status && projects.some((project: any) => project.id === task.projectId)); const highlighted = isDropTarget || isOver; return <section ref={setNodeRef} className={`min-h-56 rounded-xl border p-3 transition-colors ${highlighted ? "border-primary bg-primary/10" : "border-border bg-muted/25"}`}><header className="flex items-center justify-between gap-2"><span className="text-[11px] font-bold uppercase tracking-[0.1em] text-muted-foreground">{taskStatusLabel[status]}</span><span className="grid size-6 place-items-center rounded-full bg-card text-[10px] font-bold text-muted-foreground">{items.length}</span></header><div className="mt-3 space-y-2">{items.length ? items.map((task: any) => <KanbanTaskCard key={task.id} task={task} project={projects.find((item: any) => item.id === task.projectId)} isOwner={isOwner} onEditTask={onEditTask} onRequestMove={onRequestMove}/>) : <div className={`rounded-lg border border-dashed px-3 py-5 text-center text-xs leading-5 ${highlighted ? "border-primary/50 bg-primary/5 text-primary" : "border-border bg-card/65 text-muted-foreground"}`}>{highlighted ? "Suelta para mover aquí" : "Sin tareas."}</div>}</div></section>; }
function KanbanTaskCard({ task, project, isOwner, onEditTask, onRequestMove }: any) { const { attributes, listeners, setNodeRef, setActivatorNodeRef, transform, isDragging } = useDraggable({ id: `task-${task.id}`, disabled: !isOwner || Boolean(task.archivedAt) }); const style = { transform: CSS.Transform.toString(transform), borderLeft: `3px solid ${project?.color ?? "var(--primary)"}` }; return <article ref={setNodeRef} style={style} className={`group rounded-lg border border-border/80 bg-card shadow-sm transition-transform duration-200 ${isDragging ? "opacity-35 shadow-none" : "hover:-translate-y-0.5 hover:shadow-md"}`}><div className="flex items-start gap-1.5 p-3"><button type="button" className="min-w-0 flex-1 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary" onClick={() => onEditTask(task)}><span className="block truncate text-sm font-semibold">{task.title}</span><span className="mt-2 flex items-center justify-between gap-2 text-[10px] text-muted-foreground"><span className="truncate">{project?.name}</span><span className="shrink-0">{task.dueAt ? formatDate(task.dueAt) : "Sin fecha"}</span></span>{task.linkedTransactionId ? <span className="mt-1 flex items-center gap-1 text-[10px] text-muted-foreground"><Link2 className="size-3"/>Movimiento vinculado</span> : null}</button>{isOwner ? <button ref={setActivatorNodeRef} type="button" className="flex touch-none items-center gap-1 rounded-md px-2 py-1.5 text-[10px] font-semibold text-muted-foreground transition hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary active:cursor-grabbing" aria-label={`Arrastrar ${task.title}`} title="Mantén pulsado y arrastra esta tarea" {...attributes} {...listeners}><GripVertical className="size-4"/><span>Mover</span></button> : null}</div>{isOwner ? <div className="flex items-center gap-2 border-t px-3 py-2"><span className="text-[10px] font-medium text-muted-foreground">Mover a</span><Select value={task.status} onValueChange={(status: "pending" | "in_progress" | "waiting" | "completed") => onRequestMove(task, status)}><SelectTrigger className="h-7 flex-1 text-[10px]"><SelectValue/></SelectTrigger><SelectContent>{["pending", "in_progress", "waiting", "completed"].map(status => <SelectItem value={status} key={status}>{taskStatusLabel[status]}</SelectItem>)}</SelectContent></Select></div> : null}</article>; }
function TaskDragPreview({ task, project }: any) { return <article className="w-64 rounded-lg border border-primary/30 bg-card p-3 shadow-xl" style={{ borderLeft: `3px solid ${project?.color ?? "var(--primary)"}` }}><p className="truncate text-sm font-semibold">{task.title}</p><p className="mt-1 truncate text-[10px] text-muted-foreground">{project?.name ?? "Proyecto"}</p></article>; }

function ProjectSchedule(props: any) { return <ProjectCalendar {...props}/>; }

function buildProjectOverview(projects: any[], tasks: any[]) {
  const activeProjects = projects.filter(project => ["active", "planned", "paused"].includes(project.status)).length;
  const progress = projectProgress(tasks);
  const openTasks = tasks.filter(task => task.status !== "completed" && !task.archivedAt).length;
  return { activeProjects, totalProjects: projects.length, openTasks, closedTasks: progress.completed, totalTasks: progress.total, percent: progress.percent };
}

function ProjectHero({ overview, showArchived, isOwner, onNewProject, onOpenDraft }: any) {
  return <section className="relative overflow-hidden rounded-[2rem] border border-primary/20 bg-primary px-5 py-6 text-primary-foreground shadow-xl sm:px-7 sm:py-7"><div className="pointer-events-none absolute -right-24 -top-28 size-72 rounded-full bg-white/10"/><div className="pointer-events-none absolute bottom-0 right-24 size-32 rounded-full bg-emerald-200/10 blur-2xl"/><div className="relative grid gap-7 xl:grid-cols-[minmax(0,1fr)_auto]"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/10 px-3 py-1.5 text-[11px] font-bold uppercase tracking-[0.13em] text-emerald-50"><FolderKanban className="size-3.5"/> Planificación privada</span>{showArchived ? <span className="rounded-full bg-white/10 px-3 py-1.5 text-[11px] font-semibold text-emerald-50/85">Incluye archivados</span> : null}</div><h1 className="mt-5 max-w-xl text-3xl font-semibold leading-[0.98] tracking-[-0.055em] sm:text-4xl">Tus proyectos, <em className="font-normal text-emerald-100/90">en perspectiva.</em></h1><p className="mt-4 max-w-2xl text-sm leading-6 text-emerald-50/80">Organiza iniciativas personales y empresariales, mantén las tareas a la vista y revisa su avance sin crear movimientos ni automatizaciones financieras.</p><div className="mt-6 flex flex-wrap gap-2 text-xs text-emerald-50/85"><span className="inline-flex items-center gap-1.5 rounded-lg bg-white/10 px-3 py-2"><CheckCircle2 className="size-3.5"/> Avance automático</span><span className="inline-flex items-center gap-1.5 rounded-lg bg-white/10 px-3 py-2"><CircleDot className="size-3.5"/> Color por proyecto</span><span className="inline-flex items-center gap-1.5 rounded-lg bg-white/10 px-3 py-2"><CalendarDays className="size-3.5"/> Fechas manuales</span></div></div><div className="relative flex flex-col gap-3 xl:items-end"><div className="grid w-full grid-cols-2 gap-2 sm:w-auto sm:grid-cols-4 xl:grid-cols-2"><HeroMetric label="Proyectos activos" value={`${overview.activeProjects}`} hint={overview.totalProjects ? `${overview.totalProjects} en esta vista` : "sin proyectos"}/><HeroMetric label="Tareas abiertas" value={`${overview.openTasks}`} hint="por organizar"/><HeroMetric label="Tareas cerradas" value={`${overview.closedTasks}`} hint={overview.totalTasks ? `de ${overview.totalTasks}` : "sin tareas"}/><HeroMetric label="Avance global" value={`${overview.percent}%`} hint="tareas relevantes"/></div>{isOwner ? <div className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row"><Button variant="outline" className="border-white/25 bg-white/10 text-primary-foreground hover:bg-white/20 hover:text-primary-foreground" onClick={onOpenDraft}>Abrir borrador</Button><Button className="bg-white text-primary shadow-md hover:bg-emerald-50" onClick={onNewProject}><Plus className="mr-1.5 size-4"/>Nuevo proyecto</Button></div> : null}</div></div></section>;
}

function HeroMetric({ label, value, hint }: { label: string; value: string; hint: string }) { return <div className="rounded-xl border border-white/10 bg-black/10 px-3 py-3 backdrop-blur-sm"><span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-emerald-50/65">{label}</span><strong className="mt-1 block text-xl font-semibold tracking-[-0.04em]">{value}</strong><small className="mt-0.5 block text-[10px] text-emerald-50/65">{hint}</small></div>; }

function ProjectWorkspaceNav({ active, showArchived, onViewChange, onToggleArchived }: any) { const options = [{ value: "list", label: "Lista", icon: List }, { value: "kanban", label: "Kanban", icon: Columns3 }, { value: "calendar", label: "Calendario", icon: CalendarDays }]; return <section className="flex flex-col gap-3 rounded-2xl border bg-card/80 p-2 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div className="grid grid-cols-3 rounded-xl bg-muted/70 p-1 sm:inline-flex" role="tablist" aria-label="Vista de Proyectos">{options.map(option => { const Icon = option.icon; const selected = active === option.value; return <Button type="button" role="tab" aria-selected={selected} size="sm" variant={selected ? "default" : "ghost"} className="min-w-0 justify-center rounded-lg px-2.5 sm:px-4" key={option.value} onClick={() => onViewChange(option.value)}><Icon className="size-4 sm:mr-1.5"/><span className="hidden sm:inline">{option.label}</span><span className="sr-only sm:hidden">{option.label}</span></Button>; })}</div><Button type="button" size="sm" variant="ghost" className="justify-start text-muted-foreground sm:justify-center" onClick={onToggleArchived}><Archive className="mr-1.5 size-3.5"/>{showArchived ? "Ocultar archivados" : "Ver archivados"}</Button></section>; }

function ProjectList({ projects, milestones, tasks, progressTasks, isOwner, onEditProject, onNewMilestone, onEditMilestone, onNewTask, onEditTask, onArchiveProject, onRemoveProject, onArchiveTask, onRemoveTask, onRemoveMilestone }: any) {
  if (!projects.length) return <EmptyProjects isOwner={isOwner} onNewProject={onEditProject} />;
  return <div className="grid gap-5">{projects.map((project: any) => <ProjectCard key={project.id} project={project} milestones={milestones.filter((milestone: any) => milestone.projectId === project.id)} tasks={tasks.filter((task: any) => task.projectId === project.id)} progressTasks={progressTasks.filter((task: any) => task.projectId === project.id)} isOwner={isOwner} onEditProject={() => onEditProject(project)} onNewMilestone={() => onNewMilestone(project.id)} onEditMilestone={onEditMilestone} onNewTask={() => onNewTask(project.id)} onEditTask={onEditTask} onArchiveProject={() => onArchiveProject(project)} onRemoveProject={() => onRemoveProject(project)} onArchiveTask={onArchiveTask} onRemoveTask={onRemoveTask} onRemoveMilestone={onRemoveMilestone} />)}</div>;
}

function EmptyProjects({ isOwner, onNewProject }: any) { return <Card className="border-dashed bg-muted/20"><CardContent className="flex flex-col items-start gap-5 p-7 sm:flex-row sm:items-center"><div className="grid size-12 shrink-0 place-items-center rounded-2xl bg-primary/10 text-primary"><FolderKanban className="size-6"/></div><div className="min-w-0 flex-1"><p className="text-base font-semibold">Aún no hay proyectos en esta vista</p><p className="mt-1 max-w-xl text-sm leading-6 text-muted-foreground">Crea un proyecto personal o asociado a una entidad para organizar partes, tareas y fechas sin modificar tus registros financieros.</p></div>{isOwner ? <Button className="btn-primary" onClick={() => onNewProject(null)}><Plus className="mr-1.5 size-4"/>Crear proyecto</Button> : null}</CardContent></Card>; }

function ProjectCard({ project, milestones, tasks, progressTasks, isOwner, onEditProject, onNewMilestone, onEditMilestone, onNewTask, onEditTask, onArchiveProject, onRemoveProject, onArchiveTask, onRemoveTask, onRemoveMilestone }: any) {
  const progress = projectProgress(progressTasks);
  const visibleTaskCount = tasks.length;
  return <article className="overflow-hidden rounded-[1.6rem] border bg-card shadow-sm"><div className="h-1.5" style={{ backgroundColor: project.color }}/><div className="p-5 sm:p-6"><header className="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between"><div className="flex min-w-0 gap-3"><div className="mt-0.5 size-3 shrink-0 rounded-full shadow-sm" style={{ backgroundColor: project.color }}/><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h2 className="text-lg font-semibold tracking-[-0.03em]">{project.name}</h2><ProjectStatusBadge status={project.status}/></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{project.entityId ? "Proyecto asociado a entidad" : "Proyecto personal"}{project.targetAt ? ` · Meta ${formatDate(project.targetAt)}` : " · Sin fecha meta"}</p>{project.notes ? <p className="mt-3 max-w-3xl text-sm leading-6 text-muted-foreground">{project.notes}</p> : null}</div></div>{isOwner ? <div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={onEditProject}><Pencil className="mr-1.5 size-3.5"/>Editar</Button>{project.status !== "archived" ? <Button size="sm" variant="ghost" className="text-muted-foreground" onClick={onArchiveProject}><Archive className="mr-1.5 size-3.5"/>Archivar</Button> : null}<Button size="icon" variant="ghost" aria-label="Eliminar proyecto" className="text-muted-foreground hover:bg-rose-50 hover:text-rose-700" onClick={onRemoveProject}><Trash2 className="size-4"/></Button></div> : null}</header><div className="mt-6 grid gap-5 xl:grid-cols-[minmax(15rem,.8fr)_minmax(0,1.2fr)]"><section className="rounded-2xl border border-border/80 bg-muted/25 p-4"><div className="flex items-end justify-between gap-3"><div><p className="text-[11px] font-bold uppercase tracking-[0.12em] text-muted-foreground">Avance del proyecto</p><p className="mt-1 text-sm font-semibold">{progress.total ? `${progress.completed} de ${progress.total} tareas cerradas` : "Añade la primera tarea"}</p></div><strong className="text-2xl font-semibold tracking-[-0.05em]" style={{ color: project.color }}>{progress.percent}%</strong></div><div className="mt-4 h-2.5 overflow-hidden rounded-full bg-background" role="progressbar" aria-label={`Avance de ${project.name}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress.percent}><span className="block h-full rounded-full transition-[width] duration-200" style={{ width: `${progress.percent}%`, backgroundColor: project.color }}/></div><div className="mt-4 grid grid-cols-3 gap-2 text-center"><ProjectStat label="Partes" value={milestones.length}/><ProjectStat label="Tareas" value={visibleTaskCount}/><ProjectStat label="Meta" value={project.targetAt ? new Date(project.targetAt).toLocaleDateString("es-MX", { month: "short", day: "numeric" }) : "—"}/></div></section><div className="grid min-w-0 gap-4 lg:grid-cols-2"><ProjectSublist kind="milestone" color={project.color} items={milestones} isOwner={isOwner} onAdd={onNewMilestone} onEdit={onEditMilestone} onRemove={onRemoveMilestone}/><ProjectSublist kind="task" color={project.color} items={tasks} isOwner={isOwner} onAdd={onNewTask} onEdit={onEditTask} onArchive={onArchiveTask} onRemove={onRemoveTask}/></div></div></div></article>;
}

function ProjectStatusBadge({ status }: { status: string }) { const style = status === "active" ? "bg-emerald-100 text-emerald-800" : status === "paused" ? "bg-amber-100 text-amber-800" : status === "archived" ? "bg-slate-100 text-slate-700" : "bg-primary/10 text-primary"; return <Badge className={`${style} border-0 text-[10px] font-bold uppercase tracking-[0.08em] hover:${style}`}>{projectStatusLabel[status] ?? status}</Badge>; }
function ProjectStat({ label, value }: { label: string; value: string | number }) { return <div className="rounded-xl bg-background px-2 py-2.5"><span className="block text-[9px] font-bold uppercase tracking-[0.09em] text-muted-foreground">{label}</span><strong className="mt-1 block truncate text-xs font-semibold">{value}</strong></div>; }

function ProjectSublist({ kind, color, items, isOwner, onAdd, onEdit, onArchive, onRemove }: any) { const isTask = kind === "task"; const title = isTask ? "Tareas" : "Partes"; const Icon = isTask ? ListChecks : Target; return <section className="min-w-0 rounded-2xl border border-border/80 p-3.5"><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="grid size-7 place-items-center rounded-lg" style={{ backgroundColor: `${color}18`, color }}><Icon className="size-3.5"/></span><p className="text-xs font-bold uppercase tracking-[0.11em] text-muted-foreground">{title}</p></div>{isOwner ? <Button type="button" size="sm" variant="ghost" className="h-7 px-2 text-xs" onClick={onAdd}><Plus className="mr-1 size-3.5"/>Añadir</Button> : null}</div>{items.length ? <div className="mt-3 max-h-56 space-y-1.5 overflow-y-auto pr-1">{items.map((item: any) => <div className="group flex items-center gap-2 rounded-xl bg-muted/45 px-2.5 py-2" key={item.id}><span className="size-1.5 shrink-0 rounded-full" style={{ backgroundColor: color }}/><button type="button" className="min-w-0 flex-1 text-left" onClick={() => isOwner && onEdit(item)} disabled={!isOwner}><strong className={`block truncate text-xs font-semibold ${isTask && item.status === "completed" ? "text-muted-foreground line-through" : ""}`}>{item.title}</strong><small className="mt-0.5 block truncate text-[10px] text-muted-foreground">{isTask ? `${taskStatusLabel[item.status] ?? item.status} · ${priorityLabel[item.priority] ?? "Sin prioridad"}` : `${milestoneStatusLabel[item.status] ?? item.status}${item.targetAt ? ` · ${formatDate(item.targetAt)}` : ""}`}</small></button>{isOwner ? <div className="flex shrink-0 opacity-100 transition-opacity sm:opacity-0 sm:group-hover:opacity-100"><Button size="icon" variant="ghost" className="size-7" aria-label={`Editar ${isTask ? "tarea" : "parte"}`} onClick={() => onEdit(item)}><Pencil className="size-3.5"/></Button>{isTask && onArchive ? <Button size="icon" variant="ghost" className="size-7" aria-label={item.archivedAt ? "Restaurar tarea" : "Archivar tarea"} onClick={() => onArchive(item)}>{item.archivedAt ? <ArchiveRestore className="size-3.5"/> : <Archive className="size-3.5"/>}</Button> : null}<Button size="icon" variant="ghost" className="size-7 text-muted-foreground hover:bg-rose-50 hover:text-rose-700" aria-label={`Eliminar ${isTask ? "tarea" : "parte"}`} onClick={() => onRemove(item)}><Trash2 className="size-3.5"/></Button></div> : null}</div>)}</div> : <p className="mt-3 rounded-xl border border-dashed bg-muted/20 px-3 py-4 text-xs leading-5 text-muted-foreground">{isTask ? "Sin tareas aún. Añade una para comenzar a medir avance." : "Sin partes aún. Divide el proyecto cuando te ayude a revisarlo."}</p>}</section>; }

function ProjectKanban({ projects, tasks, isOwner, onEditTask, onNewTask }: any) { const columns = ["pending", "in_progress", "waiting", "completed"] as const; return <section className="rounded-[1.6rem] border bg-card p-4 shadow-sm sm:p-5"><div className="flex flex-col gap-3 border-b pb-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow">Flujo de trabajo</p><h2 className="mt-1 text-xl font-semibold tracking-[-0.04em]">Tablero Kanban</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Cada tarjeta conserva el color de su proyecto y abre el mismo editor de tareas que en Lista.</p></div><span className="inline-flex w-fit items-center gap-1.5 rounded-full bg-muted px-3 py-1.5 text-xs font-semibold text-muted-foreground"><CircleDot className="size-3.5"/>{tasks.length} tareas en la vista</span></div>{projects.length ? <div className="mt-5 overflow-x-auto pb-2"><div className="grid min-w-[880px] grid-cols-4 gap-4">{columns.map(status => <KanbanColumn key={status} status={status} projects={projects} tasks={tasks} isOwner={isOwner} onEditTask={onEditTask} onNewTask={onNewTask}/>)}</div></div> : <EmptyProjects isOwner={false} />}</section>; }
function KanbanColumn({ status, projects, tasks, isOwner, onEditTask, onNewTask }: any) { const columnTasks = tasks.filter((task: any) => task.status === status && projects.some((project: any) => project.id === task.projectId)); return <div className="rounded-2xl border bg-muted/25 p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold uppercase tracking-[0.11em] text-muted-foreground">{taskStatusLabel[status]}</p><span className="grid size-6 place-items-center rounded-full bg-card text-[11px] font-semibold text-muted-foreground">{columnTasks.length}</span></div><div className="mt-3 space-y-2">{columnTasks.map((task: any) => { const project = projects.find((item: any) => item.id === task.projectId); return <button type="button" className="w-full rounded-xl border-l-4 border-y border-r border-border/70 bg-card p-3 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary" style={{ borderLeftColor: project?.color }} key={task.id} onClick={() => onEditTask(task)}><span className="block truncate text-sm font-semibold">{task.title}</span><span className="mt-2 flex items-center justify-between gap-2 text-[11px] text-muted-foreground"><span className="truncate">{project?.name}</span><span className="shrink-0">{task.dueAt ? formatDate(task.dueAt) : "Sin fecha"}</span></span></button>; })}{columnTasks.length === 0 ? <div className="rounded-xl border border-dashed bg-card/65 px-3 py-5 text-center text-xs leading-5 text-muted-foreground">Sin tareas en esta etapa.</div> : null}</div>{isOwner ? <div className="mt-3 space-y-1 border-t pt-2">{projects.map((project: any) => <Button type="button" className="w-full justify-start text-xs" size="sm" variant="ghost" style={{ color: project.color }} key={project.id} onClick={() => onNewTask(project.id)}><Plus className="mr-1.5 size-3.5"/>Tarea · {project.name}</Button>)}</div> : null}</div>; }

function ProjectCalendar({ projects, milestones, tasks, isOwner, onEditTask, onEditProject }: any) { const items = buildProjectTimelineItems(projects, milestones, tasks); const projectsWithoutDates = projectsWithoutTimelineDate(projects, items); return <section className="rounded-[1.6rem] border bg-card p-4 shadow-sm sm:p-5"><div className="flex flex-col gap-3 border-b pb-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow">Calendario de proyecto</p><h2 className="mt-1 text-xl font-semibold tracking-[-0.04em]">Hitos y entregables</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">Inicios, metas, partes y tareas se muestran juntos con el color que identifica a cada proyecto.</p></div><span className="inline-flex w-fit items-center gap-1.5 rounded-full bg-muted px-3 py-1.5 text-xs font-semibold text-muted-foreground"><CalendarDays className="size-3.5"/>{items.length} fechas</span></div><div className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_18rem]"><div>{items.length ? <div className="space-y-2.5">{items.map(item => <article className="grid overflow-hidden rounded-2xl border bg-card shadow-sm sm:grid-cols-[6.5rem_1fr]" style={{ borderLeft: `4px solid ${item.project.color}` }} key={item.id}><div className="flex items-center gap-2 bg-muted/45 px-4 py-3 sm:flex-col sm:justify-center sm:gap-0"><strong className="text-base font-semibold tracking-[-0.03em]">{new Date(item.date).toLocaleDateString("es-MX", { day: "numeric", month: "short" })}</strong><span className="text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground">{new Date(item.date).toLocaleDateString("es-MX", { year: "numeric" })}</span></div><div className="min-w-0 p-4">{item.task ? <button type="button" className="w-full text-left" disabled={!isOwner} onClick={() => onEditTask(item.task)}><span className="block truncate text-sm font-semibold">{item.title}</span><span className="mt-1 block text-xs text-muted-foreground">{item.project.name} · {taskStatusLabel[item.note] ?? item.note}</span></button> : <div><p className="text-sm font-semibold">{item.title}</p><p className="mt-1 text-xs text-muted-foreground">{item.project.name} · {item.note}</p></div>}</div></article>)}</div> : <div className="rounded-2xl border border-dashed bg-muted/25 p-6 text-sm leading-6 text-muted-foreground">No hay fechas asignadas todavía. El proyecto sigue disponible en la columna de planificación para que puedas ubicarlo cuando decidas su inicio, meta o entregable.</div>}</div><aside className="rounded-2xl border border-dashed bg-muted/25 p-4"><p className="text-xs font-bold uppercase tracking-[0.11em] text-muted-foreground">Planificación sin fecha</p><p className="mt-2 text-xs leading-5 text-muted-foreground">Estos proyectos están creados y sincronizados; sólo requieren una fecha si deseas colocarlos en la línea temporal.</p>{projectsWithoutDates.length ? <div className="mt-4 space-y-2">{projectsWithoutDates.map(project => <button type="button" disabled={!isOwner} key={project.id} onClick={() => onEditProject(project)} className="flex w-full items-center gap-2 rounded-xl border bg-card px-3 py-2.5 text-left text-sm font-semibold transition hover:bg-muted/50 disabled:cursor-default"><span className="size-2 shrink-0 rounded-full" style={{ backgroundColor: project.color }}/><span className="min-w-0 flex-1 truncate">{project.name}</span>{isOwner ? <ChevronRight className="size-4 text-muted-foreground"/> : null}</button>)}</div> : <div className="mt-4 rounded-xl bg-card px-3 py-4 text-xs text-muted-foreground">Todos los proyectos de esta vista ya tienen una fecha, parte o tarea programada.</div>}</aside></div></section>; }

function ProjectForm({ project, entities, saving, planDraft, onSubmit }: any) { const defaults = planDraft ? { name: "Plan Financiero Jul–Dic 2026 · Ingresos irregulares", entityId: "none", status: "active", color: "#0f766e", startsAt: "2026-07-13", targetAt: "2026-12-31", notes: "Borrador histórico basado en el plan autorizado de Notion. Regla madre: planear sobre lo ya cobrado, no sobre ingresos esperados. Prioridades: piso vital, frenar atrasos y mínimos, compromisos operativos, obligaciones fiscales y personas, colchón, avalancha y gasto opcional sólo si lo anterior está cubierto. Revisa y sustituye los datos históricos antes de guardar." } : { name: "", entityId: "none", status: "active", color: "#0f766e", startsAt: "", targetAt: "", notes: "" }; const [form, setForm] = useState(() => project ? { ...project, entityId: project.entityId?.toString() ?? "none", startsAt: toDate(project.startsAt), targetAt: toDate(project.targetAt), notes: project.notes ?? "" } : defaults); const submit = (event: FormEvent) => { event.preventDefault(); onSubmit({ id: project?.id, name: form.name, entityId: form.entityId === "none" ? null : Number(form.entityId), status: form.status, color: form.color, startsAt: form.startsAt ? new Date(`${form.startsAt}T12:00:00`).getTime() : null, targetAt: form.targetAt ? new Date(`${form.targetAt}T12:00:00`).getTime() : null, notes: form.notes || null }); }; return <DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-xl"><DialogHeader><p className="eyebrow">Configuración del proyecto</p><DialogTitle>{project ? "Editar proyecto" : planDraft ? "Borrador de plan histórico" : "Nuevo proyecto"}</DialogTitle><DialogDescription>{planDraft ? "Este formulario no guarda nada hasta que confirmes. Las tareas y partes se crearán por separado cuando tú lo decidas." : "Un proyecto puede ser personal o asociarse a una entidad. No crea operaciones financieras."}</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-2"><Label>Nombre</Label><Input required value={form.name} onChange={event => setForm({ ...form, name: event.target.value })}/></div><div className="grid gap-4 sm:grid-cols-3"><div className="grid gap-2"><Label>Entidad</Label><Select value={form.entityId} onValueChange={value => setForm({ ...form, entityId: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Proyecto personal</SelectItem>{entities.map((entity: any) => <SelectItem key={entity.id} value={String(entity.id)}>{entity.shortCode || entity.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Estado</Label><Select value={form.status} onValueChange={value => setForm({ ...form, status: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{Object.entries(projectStatusLabel).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Color</Label><Input type="color" value={form.color} onChange={event => setForm({ ...form, color: event.target.value })}/></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Inicio</Label><Input type="date" value={form.startsAt} onChange={event => setForm({ ...form, startsAt: event.target.value })}/></div><div className="grid gap-2"><Label>Meta</Label><Input type="date" value={form.targetAt} onChange={event => setForm({ ...form, targetAt: event.target.value })}/></div></div><div className="grid gap-2"><Label>Notas privadas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} maxLength={3000}/></div><Button type="submit" className="btn-primary" disabled={saving}>{saving ? "Guardando…" : planDraft ? "Confirmar y guardar proyecto" : "Guardar proyecto"}</Button></form></DialogContent>; }
function MilestoneForm({ milestone, projectId, saving, onSubmit }: any) { const [form, setForm] = useState(() => milestone ? { ...milestone, description: milestone.description ?? "", startsAt: toDate(milestone.startsAt), targetAt: toDate(milestone.targetAt) } : { title: "", description: "", status: "planned", startsAt: "", targetAt: "" }); const submit = (event: FormEvent) => { event.preventDefault(); onSubmit({ id: milestone?.id, projectId, title: form.title, description: form.description || null, status: form.status, startsAt: form.startsAt ? new Date(`${form.startsAt}T12:00:00`).getTime() : null, targetAt: form.targetAt ? new Date(`${form.targetAt}T12:00:00`).getTime() : null }); }; return <DialogContent className="sm:max-w-lg"><DialogHeader><p className="eyebrow">Estructura del proyecto</p><DialogTitle>{milestone ? "Editar parte" : "Nueva parte del proyecto"}</DialogTitle><DialogDescription>La parte hereda el color del proyecto y no genera tareas ni eventos de forma automática.</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-2"><Label>Título</Label><Input required value={form.title} onChange={event => setForm({ ...form, title: event.target.value })}/></div><div className="grid gap-2"><Label>Estado</Label><Select value={form.status} onValueChange={value => setForm({ ...form, status: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{Object.entries(milestoneStatusLabel).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Inicio</Label><Input type="date" value={form.startsAt} onChange={event => setForm({ ...form, startsAt: event.target.value })}/></div><div className="grid gap-2"><Label>Meta</Label><Input type="date" value={form.targetAt} onChange={event => setForm({ ...form, targetAt: event.target.value })}/></div></div><div className="grid gap-2"><Label>Descripción</Label><Textarea value={form.description} onChange={event => setForm({ ...form, description: event.target.value })}/></div><Button className="btn-primary" type="submit" disabled={saving}>{saving ? "Guardando…" : "Guardar parte"}</Button></form></DialogContent>; }
function TaskForm({ task, projectId, milestones, transactions, saving, onSubmit }: any) { const [form, setForm] = useState(() => task ? { ...task, milestoneId: task.milestoneId?.toString() ?? "none", linkedTransactionId: task.linkedTransactionId?.toString() ?? "none", dueAt: toDate(task.dueAt), notes: task.notes ?? "" } : { title: "", area: "other", priority: "medium", status: "pending", milestoneId: "none", linkedTransactionId: "none", dueAt: "", requiresConfirmation: false, notes: "" }); const availableTransactions = useMemo(() => [...transactions].sort((left: any, right: any) => new Date(right.occurredAt).getTime() - new Date(left.occurredAt).getTime()).slice(0, 100), [transactions]); const submit = (event: FormEvent) => { event.preventDefault(); onSubmit({ id: task?.id, projectId, milestoneId: form.milestoneId === "none" ? null : Number(form.milestoneId), linkedTransactionId: form.linkedTransactionId === "none" ? null : Number(form.linkedTransactionId), title: form.title, area: form.area, scope: "personal", priority: form.priority, status: form.status, dueAt: form.dueAt ? new Date(`${form.dueAt}T12:00:00`).getTime() : null, goalId: null, debtId: null, requiresConfirmation: Boolean(form.requiresConfirmation), notes: form.notes || null }); }; return <DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-lg"><DialogHeader><p className="eyebrow">Acción del proyecto</p><DialogTitle>{task ? "Editar tarea" : "Nueva tarea"}</DialogTitle><DialogDescription>Heredará el color del proyecto. Puedes vincular un movimiento existente para revisarlo en contexto; no crea, duplica ni modifica movimientos.</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-2"><Label>Título</Label><Input required value={form.title} onChange={event => setForm({ ...form, title: event.target.value })}/></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Parte del proyecto</Label><Select value={form.milestoneId} onValueChange={value => setForm({ ...form, milestoneId: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Sin parte específica</SelectItem>{milestones.map((milestone: any) => <SelectItem key={milestone.id} value={String(milestone.id)}>{milestone.title}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Área</Label><Select value={form.area} onValueChange={value => setForm({ ...form, area: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{[["budget", "Presupuesto"], ["debt", "Deuda"], ["savings", "Ahorro"], ["investment", "Inversión"], ["tax", "Fiscal"], ["documents", "Documentos"], ["business", "Negocio"], ["review", "Revisión"], ["other", "Otro"]].map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div></div><div className="grid gap-2 rounded-xl border bg-muted/20 p-3"><Label>Movimiento financiero relacionado <span className="font-normal text-muted-foreground">(opcional)</span></Label><Select value={form.linkedTransactionId} onValueChange={value => setForm({ ...form, linkedTransactionId: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Sin movimiento vinculado</SelectItem>{availableTransactions.map((transaction: any) => <SelectItem key={transaction.id} value={String(transaction.id)}>{formatDate(transaction.occurredAt)} · {transaction.type === "income" ? "Ingreso" : transaction.type === "expense" ? "Gasto" : "Traspaso"} · {transaction.currency} {(transaction.amountCents / 100).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</SelectItem>)}</SelectContent></Select><p className="text-[11px] leading-5 text-muted-foreground">Muestra hasta 100 movimientos recientes. El vínculo es sólo de referencia y puedes retirarlo al editar la tarea.</p></div><div className="grid gap-4 sm:grid-cols-3"><div className="grid gap-2"><Label>Estado</Label><Select value={form.status} onValueChange={value => setForm({ ...form, status: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{Object.entries(taskStatusLabel).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Prioridad</Label><Select value={form.priority} onValueChange={value => setForm({ ...form, priority: value })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{Object.entries(priorityLabel).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Fecha</Label><Input type="date" value={form.dueAt} onChange={event => setForm({ ...form, dueAt: event.target.value })}/></div></div><label className="flex items-center gap-2 rounded-xl bg-muted/50 px-3 py-2.5 text-sm"><input type="checkbox" checked={form.requiresConfirmation} onChange={event => setForm({ ...form, requiresConfirmation: event.target.checked })}/>Requiere mi confirmación humana</label><div className="grid gap-2"><Label>Notas privadas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })}/></div><Button className="btn-primary" type="submit" disabled={saving}>{saving ? "Guardando…" : "Guardar tarea"}</Button></form></DialogContent>; }
function serializeProject(project: any) { return { id: project.id, entityId: project.entityId ?? null, name: project.name, status: project.status, color: project.color, startsAt: project.startsAt ? new Date(project.startsAt).getTime() : null, targetAt: project.targetAt ? new Date(project.targetAt).getTime() : null, notes: project.notes ?? null }; }
